StructuralRule.Predicate:
FunctionCall fc: fc.function is [
    enclosingClass.name == "System.Console" 
    and (name == "Write" or name == "WriteLine" or name == "Error")
]
/* Not accessed within main() function */
and not fc.enclosingFunction is [Function:
    name == "Main" 
    and static
    and returnType.name matches "void|int|System\.Threading\.Tasks\.Task(@1)?"
    and (
        parameterTypes.length == 0
        or (parameterTypes.length == 1 and parameterTypes[0] is [ 
            name == "System.String" and arrayDimensions == 1 
        ]) 
    )
]
/* Enclosing function is not called from main() function */
and not fc.enclosingFunction reachedBy [Function:
    name == "Main" 
    and static
    and returnType.name matches "void|int|System\.Threading\.Tasks\.Task(@1)?"
    and (
        parameterTypes.length == 0
        or (parameterTypes.length == 1 and parameterTypes[0] is [ 
            name == "System.String" and arrayDimensions == 1 
        ]) 
    )
]

FunctionCall fc:
    fc.function is [Function f:
        f.name == "AddGraphQLServer"
        and f.enclosingClass.supers contains [Class:
            name == "Microsoft.Extensions.DependencyInjection.HotChocolateAspNetCoreServiceCollectionExtensions"
        ]
    ]
    and (
        fc.enclosingFunction contains [FunctionCall fc2:
            fc2.function is [Function f2:
                f2.name == "AllowIntrospection"
                and f2.enclosingClass.supers contains [Class:
                    name == "Microsoft.Extensions.DependencyInjection.RequestExecutorBuilderExtensions"
                ]
            ]
            and fc2.arguments[1] is [Expression:
                constantValue is [Boolean: is true]
            ]
        ]*
        or not fc.enclosingFunction contains [FunctionCall fc3:
            fc3.function is [Function f3:
                f3.name == "AllowIntrospection"
                and f3.enclosingClass.supers contains [Class:
                    name == "Microsoft.Extensions.DependencyInjection.RequestExecutorBuilderExtensions"
                ]
            ]
        ]
    )

CharacterizationRule.StructuralMatch:
FunctionCall fc: 
    function is [Function:
        name == "set_FilterExpression"
        and enclosingClass.supers contains [Class:
            name == "Amazon.DynamoDBv2.Model.ScanRequest"
        ]
    ]
    and arguments[0].constantValue matches "(?i).*\s(<>|>|<|BEGINS_WITH)\s:.*"

Function:
    labels contains "AWS_Lambda_Handler"
    /* NOT triggered by API Gateway Request */
    and not labels contains "AWS_Lambda_ApiGateway"
    and parameters[0] is [Variable v:
        type.definition.supers contains [Class:
            /* We have specific sources rules for these classes */
            not name startsWith "Amazon.Lambda"
        ]    
    ]

Function:
    labels contains "AWS_Lambda_Handler"
    /* _IS_ triggered by API Gateway Request */
    and labels contains "AWS_Lambda_ApiGateway"
    and parameters[0] is [Variable v:
        type.definition.supers contains [Class:
            /* We have specific sources rules for these classes */
            not name startsWith "Amazon.Lambda"
        ]    
    ]

ReturnStatement:
